-- =============================================================================
-- Carga del Analisis de riesgo de COMPRAS (una sola vez).
-- Lo deja a nombre del comprador (fburgos@elsauz.com; si no existe ese correo, el comprador activo).
-- Despues se puede editar normal desde el portal: Analisis de riesgo.
-- Como aplicarlo: pega este archivo COMPLETO en SQL Editor y presiona Run.
-- =============================================================================
do $carga$
declare v_id uuid;
begin
  select id into v_id from public.profiles where lower(correo) = 'fburgos@elsauz.com' and activo;
  if v_id is null then
    select id into v_id from public.profiles where rol = 'comprador' and activo order by created_at limit 1;
  end if;
  if v_id is null then raise exception 'No encontre al comprador en el portal'; end if;
  if exists (select 1 from public.riesgo_analisis where created_by = v_id and proceso = 'Compras') then
    raise notice 'Ya estaba cargado el analisis de Compras; no se duplico.';
    return;
  end if;
  -- Se registra como si lo hubiera capturado el comprador (autor y area).
  perform set_config('request.jwt.claim.sub', v_id::text, true);
  perform set_config('request.jwt.claims', json_build_object('sub', v_id, 'role', 'authenticated')::text, true);
  insert into public.riesgo_analisis (proceso, fecha, actividades, created_by)
  values ('Compras', public.local_today(), $json$[{"id": "nroiixjk157k", "actividad": "Selección y evaluación de proveedores", "modos": [{"id": "9vzfjo5jnkpn", "modo": "Proveedor sin evaluación / no aprobado", "efectos": "Paro por material no conforme, rechazo de cliente, hallazgo de auditoría", "vinculado": "Proveedor", "tipo": "riesgo", "severidad": 4, "causas": "Alta de un proveedor nuevo por urgencia sin evaluarlo antes", "ocurrencia": 1, "prevencion": "Evaluación de proveedores en el portal antes de comprar", "deteccion_ctrl": "Revisión del catálogo de proveedores evaluados", "deteccion": 2, "acciones": "Mantener: no emitir OC a un proveedor sin evaluación vigente.", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "webktewoynak", "modo": "Proveedor único sin justificación", "efectos": "Riesgo de desabasto, dependencia total del proveedor, sin negociación de precio", "vinculado": "Proveedor", "tipo": "riesgo", "severidad": 4, "causas": "Artículos que solo surte un proveedor (en especial de importación) sin alterno identificado", "ocurrencia": 3, "prevencion": "Conocimiento del comprador de proveedores alternos", "deteccion_ctrl": "Se detecta cuando el proveedor falla o sube el precio", "deteccion": 3, "acciones": "Identificar los artículos de proveedor único, documentar la justificación y buscar al menos un proveedor alterno.", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}]}, {"id": "uadk0qed5j0b", "actividad": "Solicitud de cotizaciones a proveedores", "modos": [{"id": "x6578l34ia3e", "modo": "Compra sin cotización comparativa", "efectos": "Sobreprecio, pérdida de margen, favoritismos, hallazgo ISO", "vinculado": "Cláusula ISO 9001", "tipo": "riesgo", "severidad": 3, "causas": "Por tiempo o por costumbre se compra al mismo proveedor sin comparar (se hace solo a veces)", "ocurrencia": 3, "prevencion": "Catálogo de proveedores en el portal", "deteccion_ctrl": "Revisión de la OC con la gerente", "deteccion": 3, "acciones": "Definir un monto a partir del cual se piden mínimo 2 cotizaciones y dejarlas registradas con la compra.", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "y8wnno59ysem", "modo": "Especificación de compra incompleta", "efectos": "Material incorrecto, retrabajo, devoluciones, retraso operativo", "vinculado": "Requisito del cliente", "tipo": "riesgo", "severidad": 4, "causas": "La solicitud del vendedor llega sin ficha técnica, foto o medidas completas", "ocurrencia": 2, "prevencion": "Solicitud de cotización en el portal con descripción, imagen o liga de referencia", "deteccion_ctrl": "Aclaraciones con el vendedor en el chat de la partida", "deteccion": 3, "acciones": "Pedir ficha técnica o muestra al proveedor en artículos nuevos antes de la primera compra.", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "65mzh2yg4k34", "modo": "Cotización vencida o sin condiciones", "efectos": "Variación de precio al facturar, sin garantía", "vinculado": "Proveedor", "tipo": "riesgo", "severidad": 3, "causas": "Precios de importación que cambian por flete y tipo de cambio; cotizaciones sin vigencia ni Incoterm", "ocurrencia": 3, "prevencion": "Ninguno formal", "deteccion_ctrl": "Se detecta al recibir la factura del proveedor", "deteccion": 3, "acciones": "Registrar vigencia, Incoterm y condiciones de pago en cada cotización de proveedor; recotizar si está vencida.", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}]}, {"id": "6n3s3do2mh6h", "actividad": "Respuesta de cotizaciones a ventas", "modos": [{"id": "t3wrbsam37rn", "modo": "Costo mal calculado al cotizar a ventas (sin flete, aranceles, gastos de aduana o tipo de cambio)", "efectos": "Venta con margen bajo o con pérdida, precio que luego no se puede sostener", "vinculado": "Objetivo de calidad", "tipo": "riesgo", "severidad": 4, "causas": "Se cotiza con el precio del proveedor sin sumar todo el costo puesto en México", "ocurrencia": 2, "prevencion": "Costos y margen capturados en el portal por partida", "deteccion_ctrl": "Revisión de margen en la cotización", "deteccion": 3, "acciones": "Usar un cálculo de costo puesto en almacén (precio + flete + arancel + aduana + tipo de cambio) para artículos de importación.", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "x6ckmywmi1jz", "modo": "Respuesta tardía a la solicitud del vendedor", "efectos": "Pérdida de la venta, cliente insatisfecho", "vinculado": "Cliente", "tipo": "riesgo", "severidad": 3, "causas": "Carga de trabajo, espera de respuesta del proveedor", "ocurrencia": 4, "prevencion": "Plazo de respuesta configurado en el portal", "deteccion_ctrl": "Alertas automáticas del portal de solicitudes fuera de plazo", "deteccion": 2, "acciones": "Atender primero las solicitudes vencidas o por vencer del inicio del portal.", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}]}, {"id": "027orucsjpdq", "actividad": "Orden de compra", "modos": [{"id": "huhqk5jb81oh", "modo": "Compra sin orden de compra", "efectos": "Compra no autorizada, descontrol presupuestal, no existe trazabilidad", "vinculado": "Cláusula ISO 9001", "tipo": "riesgo", "severidad": 4, "causas": "Compra urgente o de bajo monto hecha por teléfono o correo", "ocurrencia": 1, "prevencion": "Toda compra se hace con OC en el portal", "deteccion_ctrl": "Conciliación de facturas contra OC", "deteccion": 2, "acciones": "", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "x073erc9lj69", "modo": "OC sin autorización", "efectos": "Gasto fuera de presupuesto, compra innecesaria", "vinculado": "Proceso", "tipo": "riesgo", "severidad": 3, "causas": "La revisión con la gerente es de palabra y no queda registro", "ocurrencia": 2, "prevencion": "Revisión de cada OC con la gerente", "deteccion_ctrl": "Ninguno registrado", "deteccion": 3, "acciones": "Dejar registro de la revisión de la gerente en la OC (visto bueno en el portal o firma).", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "c5e1x8pyusqo", "modo": "OC con datos erróneos o que cambia al embarcar", "efectos": "Pago incorrecto, material incompleto, diferencia de inventario", "vinculado": "Proveedor", "tipo": "riesgo", "severidad": 3, "causas": "La OC de importación se hace antes de saber lo que realmente cabe en el contenedor; al final cambian cantidades", "ocurrencia": 4, "prevencion": "Revisión de la OC con la gerente", "deteccion_ctrl": "Comparación contra la factura y lista de empaque al final", "deteccion": 3, "acciones": "Actualizar la OC (revisión) cuando el proveedor confirme la lista de empaque, antes de pagar el saldo.", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}]}, {"id": "n0p15vnunzk1", "actividad": "Seguimiento a entregas", "modos": [{"id": "hc712erg3ir8", "modo": "Entrega fuera de tiempo / retraso (principalmente China)", "efectos": "Pérdida de venta, flete urgente, multa de cliente", "vinculado": "Cliente", "tipo": "riesgo", "severidad": 4, "causas": "Tiempos de producción, puerto, naviera, aduana y temporadas (Año Nuevo Chino); los locales rara vez", "ocurrencia": 4, "prevencion": "Pedir con anticipación", "deteccion_ctrl": "Seguimiento con el proveedor y el agente aduanal", "deteccion": 3, "acciones": "Manejar fecha de embarque y llegada estimada por OC, agregar colchón de tránsito y avisar a ventas los retrasos.", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "1ikhrsy6xm58", "modo": "No dar seguimiento al pedido", "efectos": "Desconocimiento de estatus, incumplimiento a clientes", "vinculado": "Cliente", "tipo": "riesgo", "severidad": 4, "causas": "Muchas OC abiertas al mismo tiempo sin un control único", "ocurrencia": 2, "prevencion": "Registro de OC en el portal", "deteccion_ctrl": "Revisión de OC abiertas", "deteccion": 3, "acciones": "Revisión semanal de OC abiertas con su estatus.", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "0qdthhr7uywe", "modo": "Aviso de retraso a último momento", "efectos": "Sin tiempo de reacción, compra de emergencia con costo elevado", "vinculado": "Proveedor", "tipo": "riesgo", "severidad": 4, "causas": "El proveedor no avisa hasta la fecha de embarque", "ocurrencia": 3, "prevencion": "Ninguno formal", "deteccion_ctrl": "Solo se detecta cuando no llega", "deteccion": 4, "acciones": "Pedir al proveedor confirmación de fecha de embarque y número de guía o BL una semana antes.", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}]}, {"id": "op65fenqekls", "actividad": "Recepción e inspección (entrada de la compra con factura)", "modos": [{"id": "4lq8xch0k0e5", "modo": "Material no conforme / dañado", "efectos": "Devolución, retrabajo, reclamo del cliente, paro del proceso operativo", "vinculado": "Producto", "tipo": "riesgo", "severidad": 4, "causas": "Falla de calidad del proveedor o daño en tránsito", "ocurrencia": 2, "prevencion": "Evaluación de proveedores", "deteccion_ctrl": "Inspección de almacén al recibir", "deteccion": 3, "acciones": "Que almacén reporte a compras el mismo día cualquier daño para reclamar al proveedor o a la aseguradora.", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "aibmb1qmph21", "modo": "Cantidad diferente a la OC", "efectos": "Faltante para vender, sobrante, inventario incorrecto", "vinculado": "Proceso", "tipo": "riesgo", "severidad": 3, "causas": "Lo embarcado cambia según lo que cabe en el contenedor", "ocurrencia": 4, "prevencion": "Lista de empaque del proveedor", "deteccion_ctrl": "Conteo de almacén y entrada de la compra con factura", "deteccion": 3, "acciones": "Conciliar OC, lista de empaque, factura y conteo de almacén al dar entrada a la compra.", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "n4rg965a1kxj", "modo": "Material sin certificado / lote", "efectos": "No conformidad, sin rastreabilidad", "vinculado": "Requisito del cliente", "tipo": "riesgo", "severidad": 3, "causas": "Todavía no está definido qué artículos requieren lote o certificado", "ocurrencia": 3, "prevencion": "Ninguno", "deteccion_ctrl": "Ninguno", "deteccion": 5, "acciones": "Definir qué artículos requieren lote o certificado, pedirlo en la OC y registrar el lote al recibir.", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}]}, {"id": "kifzvpy518jz", "actividad": "Facturación y precios", "modos": [{"id": "xqwq2yo7nlo7", "modo": "Factura con precio o cantidad diferente a la OC", "efectos": "Pago incorrecto, pérdida económica, diferencia contable", "vinculado": "Proveedor", "tipo": "riesgo", "severidad": 3, "causas": "La OC no se actualiza cuando cambia lo embarcado", "ocurrencia": 4, "prevencion": "Revisión de la OC con la gerente", "deteccion_ctrl": "Comparación de factura contra OC al registrar la compra", "deteccion": 3, "acciones": "Misma acción que OC con datos erróneos: actualizar la OC antes de pagar y conciliar contra la factura.", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "xab6pfqxkqh7", "modo": "Factura sin OC o duplicada", "efectos": "Pago duplicado, descontrol, hallazgos en auditoría", "vinculado": "Proceso", "tipo": "riesgo", "severidad": 3, "causas": "Proveedor que envía la factura dos veces o por otro medio", "ocurrencia": 1, "prevencion": "Toda compra con OC", "deteccion_ctrl": "Revisión de pagos en el portal", "deteccion": 3, "acciones": "", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "o3jn2scpyeql", "modo": "Error en condiciones de pago o moneda", "efectos": "Pago anticipado indebido, afectación del flujo", "vinculado": "Proceso", "tipo": "riesgo", "severidad": 4, "causas": "Confusión entre USD y MXN, anticipo y saldo", "ocurrencia": 2, "prevencion": "Moneda y condiciones capturadas en la OC del portal", "deteccion_ctrl": "Revisión del pago antes de mandarlo", "deteccion": 3, "acciones": "", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}]}, {"id": "eka9echfqir9", "actividad": "Importación y aduana", "modos": [{"id": "oyjmss4m18ht", "modo": "Carta 3.1.8 o pedimento con datos erróneos", "efectos": "Multa o retención de la mercancía en aduana, retraso", "vinculado": "Requisito legal", "tipo": "riesgo", "severidad": 4, "causas": "Datos de la factura y la OC no coinciden o se capturan a mano", "ocurrencia": 2, "prevencion": "Formato de carta 3.1.8 armado desde la OC y factura", "deteccion_ctrl": "Revisión del agente aduanal", "deteccion": 3, "acciones": "Revisar la carta contra factura y lista de empaque antes de firmarla.", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "5wfweo4gehf6", "modo": "Fracción arancelaria equivocada", "efectos": "Pago de impuestos incorrecto, multa, retención", "vinculado": "Requisito legal", "tipo": "riesgo", "severidad": 4, "causas": "Artículo nuevo sin clasificación previa", "ocurrencia": 2, "prevencion": "Clasificación del agente aduanal", "deteccion_ctrl": "Revisión del pedimento", "deteccion": 3, "acciones": "Llevar un listado de fracciones por artículo de importación validado con el agente aduanal.", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "k2radr7zvif5", "modo": "Mercancía que requiere NOM o etiquetado y llega sin ella", "efectos": "Mercancía detenida, reetiquetado, multa", "vinculado": "Requisito legal", "tipo": "riesgo", "severidad": 4, "causas": "No se revisa si el artículo requiere NOM antes de comprarlo", "ocurrencia": 2, "prevencion": "Consulta al agente aduanal", "deteccion_ctrl": "Revisión en aduana", "deteccion": 3, "acciones": "Revisar requisitos de NOM y etiquetado al dar de alta un artículo nuevo de importación.", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}]}, {"id": "x8be00lfixam", "actividad": "Pagos internacionales", "modos": [{"id": "vh1ut82bpdsm", "modo": "Variación del tipo de cambio", "efectos": "Costo mayor al cotizado, pérdida de margen